function Nav() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => {
    const h = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", h, { passive: true });
    return () => window.removeEventListener("scroll", h);
  }, []);

  const links = [
    { id: "packages", label: "PACKAGES" },
    { id: "addons", label: "ADD-ONS" },
    { id: "faq", label: "FAQ" },
    { id: "contact", label: "CONTACT" },
    { id: "booking", label: "BOOK" }
  ];

  return (
    <nav style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 1000,
      background: scrolled ? "rgba(10,10,15,0.95)" : "transparent",
      borderBottom: scrolled ? pxBorder(C.border) : "2px solid transparent",
      transition: "all 0.3s", padding: "0 20px"
    }}>
      <div style={{ maxWidth: 1000, margin: "0 auto", display: "flex", alignItems: "center", justifyContent: "space-between", height: 56 }}>
        <button onClick={() => scrollTo("hero")} style={{
          background: "none", border: "none", cursor: "pointer",
          display: "flex", alignItems: "center", gap: 8, padding: 0
        }}>
          <img src={LOGO_URI} alt="U-PIC" style={{ height: 32, width: 32, objectFit: "contain" }} />
          <span style={{
            fontFamily: "'Press Start 2P', monospace", fontSize: 12,
            color: C.neonPink, textShadow: txtGlow(C.neonPink)
          }}>U-PIC</span>
        </button>
        <button onClick={() => setMenuOpen(!menuOpen)} className="mob-btn" style={{
          display: "none", background: "none", border: "none",
          fontFamily: "'Press Start 2P', monospace", fontSize: 16,
          color: C.neonCyan, cursor: "pointer"
        }}>
          {menuOpen ? "X" : "="}
        </button>
        <div className={`nav-lnk ${menuOpen ? "open" : ""}`}>
          {links.map((l) => (
            <button key={l.id} onClick={() => { scrollTo(l.id); setMenuOpen(false); }} style={{
              background: l.id === "booking" ? C.neonPink : "transparent",
              border: "none", cursor: "pointer",
              fontFamily: "'Press Start 2P', monospace", fontSize: 11,
              color: l.id === "booking" ? "#000" : C.gray,
              padding: l.id === "booking" ? "8px 16px" : "6px 0",
              transition: "color 0.2s", letterSpacing: 1
            }}
              onMouseEnter={(e) => { if (l.id !== "booking") e.target.style.color = C.neonCyan; }}
              onMouseLeave={(e) => { if (l.id !== "booking") e.target.style.color = C.gray; }}
            >
              {l.label}
            </button>
          ))}
        </div>
      </div>
    </nav>
  );
}

